package br.com.onda;
import android.content.*;import android.net.Uri;import android.graphics.*;import java.io.*;import java.nio.file.*;import java.util.*;import androidx.core.content.FileProvider;
final class ImageSharing {
 static File folder(Context c){File dir=new File(c.getCacheDir(),"shares/images");dir.mkdirs();File[] old=dir.listFiles();if(old!=null)for(File f:old)if(System.currentTimeMillis()-f.lastModified()>48L*60*60*1000)f.delete();return dir;}
 static Intent card(Context c,String title,String message,int style)throws IOException{Bitmap bitmap=MessageCardArt.draw(title,message,style,1080);File out=new File(folder(c),"Onda-mensagem-"+UUID.randomUUID()+".png");try(OutputStream stream=new FileOutputStream(out)){if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,stream))throw new IOException("Não foi possível criar a imagem.");}finally{bitmap.recycle();}return send(c,out,"image/png",title);}
 static Intent photo(Context c,ImageCatalog.Photo photo,File source)throws IOException{return copy(c,source,photo.attribution());}
 static Intent web(Context c,File source)throws IOException{return copy(c,source,null);}
 private static Intent copy(Context c,File source,String text)throws IOException{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(source.toString(),bounds);if(bounds.outWidth<=0||bounds.outHeight<=0||bounds.outMimeType==null||!Arrays.asList("image/png","image/jpeg","image/webp","image/gif").contains(bounds.outMimeType))throw new IOException("A imagem recebida não é compatível.");String mime=bounds.outMimeType,extension=mime.equals("image/png")?".png":mime.equals("image/webp")?".webp":mime.equals("image/gif")?".gif":".jpg";File out=new File(folder(c),"Onda-imagem-"+UUID.randomUUID()+extension);Files.copy(source.toPath(),out.toPath());return send(c,out,mime,text);}
 static Intent send(Context c,File file,String mime,String text){Uri uri=FileProvider.getUriForFile(c,c.getPackageName()+".share",file);Intent send=new Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(text!=null&&!text.isEmpty())send.putExtra(Intent.EXTRA_TEXT,text);send.setClipData(ClipData.newUri(c.getContentResolver(),"Imagem do Onda",uri));return send;}
}
